<?php $this->layout('default'); use Moves\Services\CmsAuth; use Moves\Services\PlatformDirectory; use Moves\Support\CmsView as V;
$d = PlatformDirectory::dashboard();
$kpi = static fn (string $label, string $value): string => '<div class="cms-kpi"><span>' . V::e($label) . '</span><strong>' . V::e($value) . '</strong></div>';
$canCommercial = CmsAuth::can($admin, 'subscriptions.view'); $canPlatform = CmsAuth::can($admin, 'users.view'); $canTickets = CmsAuth::can($admin, 'tickets.view'); ?>
<?php if ($canPlatform): ?><h2>Plataforma</h2><div class="cms-kpis"><?= $kpi('Usuários cadastrados', (string) $d['users_total']) . $kpi('Usuários ativos', (string) $d['users_active']) . $kpi('Novos cadastros em 30 dias', (string) $d['users_new_30']) . $kpi('Empresas cadastradas', (string) $d['companies_total']) ?></div><?php endif; ?>
<?php if ($canCommercial): ?><h2>Comercial</h2><div class="cms-kpis"><?= $kpi('Assinaturas ativas', (string) ($d['subs']['active'] ?? 0)) . $kpi('Assinaturas pendentes', (string) ($d['subs']['pending'] ?? 0)) . $kpi('Assinaturas canceladas', (string) ($d['subs']['canceled'] ?? 0)) . $kpi('Planos contratados', (string) $d['plans_contracted']) . $kpi('Cobranças pendentes', (string) $d['charges_pending']) . $kpi('Receita recorrente mensal', V::money($d['mrr'])) ?></div><?php endif; ?>
<?php if ($canTickets): ?><h2>Atendimento</h2><div class="cms-kpis"><?= $kpi('Chamados abertos', (string) ($d['tickets']['open'] ?? 0)) . $kpi('Chamados pendentes', (string) $d['tickets_pending']) . $kpi('Em atendimento', (string) ($d['tickets']['in_progress'] ?? 0)) . $kpi('Resolvidos', (string) (($d['tickets']['resolved'] ?? 0) + ($d['tickets']['closed'] ?? 0))) . $kpi('Primeira resposta (média)', V::minutes($d['first_response_avg'])) . $kpi('Resolução (média)', V::minutes($d['resolution_avg'])) ?></div><?php endif; ?>
